// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md: zero wait states, no state machine, the
// only state is the four registers. Interface per interface_spec.md.
module apb_regs #(
  parameter ADDR_WIDTH = 8,
  parameter DATA_WIDTH = 32
) (
  input  wire                    pclk,
  input  wire                    presetn,
  input  wire [ADDR_WIDTH-1:0]   paddr,
  input  wire                    psel,
  input  wire                    penable,
  input  wire                    pwrite,
  input  wire [DATA_WIDTH-1:0]   pwdata,
  input  wire [DATA_WIDTH/8-1:0] pstrb,
  output wire [DATA_WIDTH-1:0]   prdata,
  output wire                    pready,
  output wire                    pslverr
);

  localparam STRB_WIDTH = DATA_WIDTH / 8;

  // Byte merge: copy each byte of new_v whose strobe is set, keep the rest.
  function [DATA_WIDTH-1:0] merge;
    input [DATA_WIDTH-1:0] old_v;
    input [DATA_WIDTH-1:0] new_v;
    input [STRB_WIDTH-1:0] strb_v;
    integer i;
    begin
      merge = old_v;
      for (i = 0; i < STRB_WIDTH; i = i + 1) begin
        if (strb_v[i]) begin
          merge[8*i +: 8] = new_v[8*i +: 8];
        end
      end
    end
  endfunction

  // Register state
  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;

  // Access strobe and address decode
  wire       access        = psel && penable;
  wire       addr_aligned  = (paddr[1:0] == 2'b00);
  wire       addr_in_range = (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
  wire       mapped        = addr_aligned && addr_in_range;
  wire [1:0] idx           = paddr[3:2];

  wire wr_en = access && pwrite && mapped;
  wire rd_en = access && !pwrite && mapped;

  wire wr0 = wr_en && (idx == 2'd0);
  wire wr1 = wr_en && (idx == 2'd1);
  wire wr2 = wr_en && (idx == 2'd2);
  wire wr3 = wr_en && (idx == 2'd3);

  // Next state
  wire [DATA_WIDTH-1:0] reg0_d = wr0 ? merge(reg0, pwdata, pstrb) : reg0;
  wire [DATA_WIDTH-1:0] reg1_d = wr1 ? merge(reg1, pwdata, pstrb) : reg1;
  wire [DATA_WIDTH-1:0] reg2_d = wr2 ? merge(reg2, pwdata, pstrb) : reg2;
  wire [DATA_WIDTH-1:0] reg3_d = wr3 ? merge(reg3, pwdata, pstrb) : reg3;

  // Register block: synchronous, active-low reset
  always @(posedge pclk) begin
    if (!presetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
      reg1 <= {DATA_WIDTH{1'b0}};
      reg2 <= {DATA_WIDTH{1'b0}};
      reg3 <= {DATA_WIDTH{1'b0}};
    end else begin
      reg0 <= reg0_d;
      reg1 <= reg1_d;
      reg2 <= reg2_d;
      reg3 <= reg3_d;
    end
  end

  // Read multiplexer
  reg [DATA_WIDTH-1:0] rd_mux;
  always @* begin
    rd_mux = {DATA_WIDTH{1'b0}};
    case (idx)
      2'd0:    rd_mux = reg0;
      2'd1:    rd_mux = reg1;
      2'd2:    rd_mux = reg2;
      2'd3:    rd_mux = reg3;
      default: rd_mux = {DATA_WIDTH{1'b0}};
    endcase
  end

  // Responses
  assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
  assign pready  = 1'b1;
  assign pslverr = access && !mapped;

`ifdef FORMAL
  // Design-intent properties (microarchitecture.md section 6). Decode and
  // byte checks are written independently of `mapped` and `merge`.
  localparam [ADDR_WIDTH-1:0] F_A0 = 0;
  localparam [ADDR_WIDTH-1:0] F_A4 = 4;
  localparam [ADDR_WIDTH-1:0] F_A8 = 8;
  localparam [ADDR_WIDTH-1:0] F_AC = 12;

  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk) f_past_valid <= 1'b1;

  // Manager assumptions
  always @(*) begin
    if (!f_past_valid) assume(!presetn);
    if (!presetn) assume(!psel);
    if (penable) assume(psel);
  end

  always @(posedge pclk) begin
    if (f_past_valid) begin
      if (penable) begin
        assume($past(presetn) && $past(psel) && !$past(penable));
      end
      if ($past(presetn) && $past(psel) && !$past(penable) && presetn) begin
        assume(psel && penable);
        assume(paddr  == $past(paddr));
        assume(pwrite == $past(pwrite));
        assume(pwdata == $past(pwdata));
        assume(pstrb  == $past(pstrb));
      end
    end
  end

  wire f_access = psel && penable;
  wire f_mapped = (paddr == F_A0) || (paddr == F_A4) ||
                  (paddr == F_A8) || (paddr == F_AC);

  reg [DATA_WIDTH-1:0] f_rd;
  always @(*) begin
    f_rd = {DATA_WIDTH{1'b0}};
    if (paddr == F_A0) f_rd = reg0;
    if (paddr == F_A4) f_rd = reg1;
    if (paddr == F_A8) f_rd = reg2;
    if (paddr == F_AC) f_rd = reg3;
  end

  always @(*) begin
    assert(pready);
    if (!f_access) begin
      assert(prdata == {DATA_WIDTH{1'b0}});
      assert(!pslverr);
    end else begin
      assert(pslverr == !f_mapped);
      if (f_mapped && !pwrite) begin
        assert(prdata == f_rd);
      end else begin
        assert(prdata == {DATA_WIDTH{1'b0}});
      end
    end
  end

  wire [4*DATA_WIDTH-1:0] f_regs = {reg3, reg2, reg1, reg0};

  genvar fr, fb;
  generate
    for (fr = 0; fr < 4; fr = fr + 1) begin : g_f_reg
      for (fb = 0; fb < STRB_WIDTH; fb = fb + 1) begin : g_f_byte
        always @(posedge pclk) begin
          if (f_past_valid) begin
            if (!$past(presetn)) begin
              assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] == 8'h00);
            end else if ($past(f_access && pwrite && pstrb[fb] && (paddr == fr*4))) begin
              assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] == $past(pwdata[8*fb +: 8]));
            end else begin
              assert(f_regs[fr*DATA_WIDTH + 8*fb +: 8] == $past(f_regs[fr*DATA_WIDTH + 8*fb +: 8]));
            end
          end
        end
      end
    end
  endgenerate

  always @(*) begin
    cover(f_access && pwrite && f_mapped && (pstrb != {STRB_WIDTH{1'b0}}));
    cover(f_access && !pwrite && f_mapped && (prdata != {DATA_WIDTH{1'b0}}));
    cover(pslverr);
  end
`endif

endmodule
=== END FILE ===
