// apb_regs_tb: directed self-checking testbench for apb_regs.
// Inputs change on the falling edge; outputs are checked 2 time units later,
// before the next rising edge, so there is no race with the design.
module apb_regs_tb;

  reg         pclk = 1'b0;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  integer passed;
  integer failed;
  integer step;
  integer ok;
  integer k;
  reg [8*64-1:0] nonce;

  // Expected-value model of the four registers
  reg [31:0] model [0:3];

  apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
    .pclk    (pclk),
    .presetn (presetn),
    .paddr   (paddr),
    .psel    (psel),
    .penable (penable),
    .pwrite  (pwrite),
    .pwdata  (pwdata),
    .pstrb   (pstrb),
    .prdata  (prdata),
    .pready  (pready),
    .pslverr (pslverr)
  );

  always #5 pclk = ~pclk;

  // ---------------------------------------------------------------- model
  function tb_mapped;
    input [7:0] a;
    begin
      tb_mapped = (a == 8'h00) || (a == 8'h04) || (a == 8'h08) || (a == 8'h0C);
    end
  endfunction

  function [31:0] tb_merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  s;
    begin
      tb_merge[7:0]   = s[0] ? new_v[7:0]   : old_v[7:0];
      tb_merge[15:8]  = s[1] ? new_v[15:8]  : old_v[15:8];
      tb_merge[23:16] = s[2] ? new_v[23:16] : old_v[23:16];
      tb_merge[31:24] = s[3] ? new_v[31:24] : old_v[31:24];
    end
  endfunction

  // ---------------------------------------------------------------- checks
  task check_eq;
    input [31:0] got;
    input [31:0] exp;
    input [31:0] id;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("apb_regs_tb: check %0d failed at time %0t: got 0x%08h, expected 0x%08h",
               id, $time, got, exp);
      end
    end
  endtask

  // ---------------------------------------------------------------- bus tasks
  // One idle cycle (psel low) with an arbitrary address and direction;
  // responses must be quiet.
  task bus_idle;
    input [7:0] addr;
    input       wr;
    begin
      @(negedge pclk);
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = wr;
      paddr   = addr;
      pwdata  = 32'hDEAD_BEEF;
      pstrb   = 4'h0;
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 0);
      check_eq(prdata, 32'd0, step*16 + 1);
      step = step + 1;
    end
  endtask

  // A complete write transfer: setup then a single-cycle access.
  task apb_write;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    reg          exp_err;
    begin
      exp_err = !tb_mapped(addr);
      // setup phase
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = 1'b1;
      paddr   = addr;
      pwdata  = data;
      pstrb   = strb;
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 2);
      check_eq(prdata, 32'd0, step*16 + 3);
      // access phase: zero wait states
      @(negedge pclk);
      penable = 1'b1;
      #2;
      check_eq({31'd0, pready}, 32'd1, step*16 + 4);
      check_eq({31'd0, pslverr}, {31'd0, exp_err}, step*16 + 5);
      check_eq(prdata, 32'd0, step*16 + 6);
      if (!exp_err) begin
        model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
      end
      step = step + 1;
    end
  endtask

  // A complete read transfer: setup then a single-cycle access.
  task apb_read;
    input [7:0] addr;
    reg         exp_err;
    reg [31:0]  exp_data;
    begin
      exp_err  = !tb_mapped(addr);
      exp_data = exp_err ? 32'd0 : model[addr[3:2]];
      // setup phase
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = 1'b0;
      paddr   = addr;
      pwdata  = 32'd0;
      pstrb   = 4'h0;
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 7);
      check_eq(prdata, 32'd0, step*16 + 8);
      // access phase: zero wait states
      @(negedge pclk);
      penable = 1'b1;
      #2;
      check_eq({31'd0, pready}, 32'd1, step*16 + 9);
      check_eq({31'd0, pslverr}, {31'd0, exp_err}, step*16 + 10);
      check_eq(prdata, exp_data, step*16 + 11);
      step = step + 1;
    end
  endtask

  // Reset with psel low for three cycles, then release.
  task bus_reset;
    begin
      @(negedge pclk);
      presetn = 1'b0;
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      paddr   = 8'h00;
      pwdata  = 32'd0;
      pstrb   = 4'h0;
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 12);
      check_eq(prdata, 32'd0, step*16 + 13);
      @(negedge pclk);
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 12);
      check_eq(prdata, 32'd0, step*16 + 13);
      @(negedge pclk);
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 12);
      check_eq(prdata, 32'd0, step*16 + 13);
      model[0] = 32'd0;
      model[1] = 32'd0;
      model[2] = 32'd0;
      model[3] = 32'd0;
      @(negedge pclk);
      presetn = 1'b1;
      #2;
      check_eq({31'd0, pslverr}, 32'd0, step*16 + 14);
      check_eq(prdata, 32'd0, step*16 + 15);
      step = step + 1;
    end
  endtask

  // ---------------------------------------------------------------- watchdog
  initial begin
    #200000;
    $fatal(1, "apb_regs_tb: timeout");
  end

  // ---------------------------------------------------------------- stimulus
  initial begin
    passed  = 0;
    failed  = 0;
    step    = 0;
    ok      = 0;
    nonce   = {8*64{1'b0}};
    presetn = 1'b0;
    psel    = 1'b0;
    penable = 1'b0;
    pwrite  = 1'b0;
    paddr   = 8'h00;
    pwdata  = 32'd0;
    pstrb   = 4'h0;
    model[0] = 32'd0;
    model[1] = 32'd0;
    model[2] = 32'd0;
    model[3] = 32'd0;

    // 1. Reset, then reset values of every register (back-to-back reads)
    bus_reset;
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);
    bus_idle(8'h00, 1'b0);

    // 2. Full-word writes to every register, back to back, then read back
    apb_write(8'h00, 32'hA5A5_0001, 4'hF);
    apb_write(8'h04, 32'h5A5A_0002, 4'hF);
    apb_write(8'h08, 32'h0123_4567, 4'hF);
    apb_write(8'h0C, 32'h89AB_CDEF, 4'hF);
    bus_idle(8'h04, 1'b1);
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);

    // 3. Write followed directly by a read, and idle gaps with selects low
    apb_write(8'h04, 32'hCAFE_F00D, 4'hF);
    apb_read(8'h04);
    apb_write(8'h08, 32'h1357_9BDF, 4'hF);
    apb_read(8'h08);
    apb_read(8'h00);
    bus_idle(8'h08, 1'b1);
    bus_idle(8'h0C, 1'b0);
    bus_idle(8'h00, 1'b1);
    apb_read(8'h0C);
    bus_idle(8'h00, 1'b0);

    // 4. Every strobe pattern on REG2, each read back
    for (k = 0; k < 16; k = k + 1) begin
      apb_write(8'h08, 32'hF0E1_D2C3 + k * 32'h0102_0304, k[3:0]);
      apb_read(8'h08);
    end
    bus_idle(8'h00, 1'b0);

    // Partial writes on the other registers
    apb_write(8'h00, 32'h1122_3344, 4'b0001);
    apb_write(8'h04, 32'h5566_7788, 4'b0110);
    apb_write(8'h0C, 32'h99AA_BBCC, 4'b1000);
    apb_write(8'h0C, 32'hFFFF_FFFF, 4'b0000);
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h0C);
    bus_idle(8'h00, 1'b0);

    // 5. Unmapped writes: misaligned and out of range, including aliases
    apb_write(8'h01, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h02, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h03, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h05, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h0E, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h10, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h14, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h18, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h40, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h9C, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'hFF, 32'hFFFF_FFFF, 4'hF);
    apb_write(8'h11, 32'hFFFF_FFFF, 4'h0);
    bus_idle(8'h00, 1'b0);
    // Mapped registers must be unchanged
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);

    // Unmapped reads: pslverr high, prdata zero
    apb_read(8'h01);
    apb_read(8'h02);
    apb_read(8'h03);
    apb_read(8'h06);
    apb_read(8'h0D);
    apb_read(8'h10);
    apb_read(8'h14);
    apb_read(8'h18);
    apb_read(8'h1C);
    apb_read(8'h80);
    apb_read(8'hFC);
    apb_read(8'hFF);

    // Unmapped and mapped transfers back to back
    apb_write(8'h10, 32'h0BAD_0BAD, 4'hF);
    apb_read(8'h00);
    apb_read(8'h20);
    apb_write(8'h00, 32'h600D_600D, 4'hF);
    apb_read(8'h00);
    bus_idle(8'h10, 1'b1);
    bus_idle(8'h10, 1'b0);

    // 6. Reset again with non-zero contents, then reset values
    apb_write(8'h04, 32'h7777_7777, 4'hF);
    apb_write(8'h08, 32'h8888_8888, 4'hF);
    apb_write(8'h0C, 32'h9999_9999, 4'hF);
    bus_idle(8'h00, 1'b0);
    bus_reset;
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);

    // 7. Block works after the second reset
    apb_write(8'h04, 32'h0F0F_F0F0, 4'b1010);
    apb_read(8'h04);
    bus_idle(8'h00, 1'b0);
    bus_idle(8'h00, 1'b0);

    // Verdict
    ok = $value$plusargs("nirmaan_nonce=%s", nonce);
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
